from pathlib import Path
import json,hashlib,numpy as np
D=Path(__file__).resolve().parent;W=D.parents[1];C=W/'experiments/source_confidence_calibration_20261012_v1';FBASE=.6*584.8888888888889;out=D/'predictions';out.mkdir(exist_ok=False);identities={};rows=[]
