 e=np.array(errors);r=dict(sequence=name,calibration_available=row['calibration_available'],bias_px=row['bias_px'],first_calibration_frame=row['first_calibration_frame'],max_anchor_points=max(x['anchors'] for x in row['epochs']),depth_p90_m=float(np.quantile(e,.9)),above030_fraction=float((e>.3).mean()),obstacle_retention=obsk/max(1,obs),candidate_retention=nk/max(1,n));r['gate']=bool(r['calibration_available'] and r['depth_p90_m']<=.15 and r['above030_fraction']<=.1 and r['obstacle_retention']>=.95 and r['candidate_retention']>=.7);results.append(r)
